// SearXNG returns { query, results: [{ url, title, content, engine }], ... }.
// Keep the top N, drop anything without a URL, and trim snippets so a
// long result set cannot overrun the model's context window.
const payload = $input.first().json;
const wanted = $('Search Terms').first().json.max_results || 8;
const results = Array.isArray(payload.results) ? payload.results : [];

const top = results
  .filter((r) => r && r.url)
  .slice(0, wanted)
  .map((r, i) => ({
    rank: i + 1,
    title: (r.title || '').trim(),
    url: r.url,
    snippet: (r.content || '').trim().slice(0, 400),
    engine: r.engine || '',
  }));

return [{
  json: {
    query: $('Search Terms').first().json.query,
    result_count: top.length,
    results: top,
    digest_input: top
      .map((r) => `[${r.rank}] ${r.title}\n${r.url}\n${r.snippet}`)
      .join('\n\n'),
  },
}];

